PRAGMA foreign_keys = ON;
CREATE TABLE accounts (id TEXT PRIMARY KEY, name TEXT NOT NULL, institution TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'checking', currency TEXT NOT NULL DEFAULT 'USD', balance INTEGER NOT NULL DEFAULT 0, balance_at TEXT, source TEXT NOT NULL DEFAULT 'manual', provider_id TEXT UNIQUE, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, type TEXT NOT NULL CHECK(type IN ('income','expense','transfer')), tax_treatment TEXT NOT NULL DEFAULT 'personal' CHECK(tax_treatment IN ('personal','business_income','business_expense','tax_payment','excluded')), color TEXT NOT NULL DEFAULT '#28634a');
CREATE TABLE transactions (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), provider_id TEXT, posted TEXT NOT NULL, amount INTEGER NOT NULL, description TEXT NOT NULL, merchant TEXT NOT NULL DEFAULT '', category_id TEXT REFERENCES categories(id), type TEXT NOT NULL CHECK(type IN ('income','expense','transfer')), notes TEXT NOT NULL DEFAULT '', pending INTEGER NOT NULL DEFAULT 0, reviewed INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL DEFAULT 'manual', raw_json TEXT, user_edited INTEGER NOT NULL DEFAULT 0, rule_id TEXT, transfer_id TEXT, import_id TEXT, deleted INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(account_id,provider_id));
CREATE INDEX tx_date ON transactions(posted DESC,id);
CREATE INDEX tx_account_date ON transactions(account_id,posted);
CREATE INDEX tx_category ON transactions(category_id,posted);
CREATE INDEX tx_review ON transactions(reviewed,deleted);
CREATE TABLE splits (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, amount INTEGER NOT NULL, category_id TEXT REFERENCES categories(id), type TEXT NOT NULL CHECK(type IN ('income','expense','transfer')), notes TEXT NOT NULL DEFAULT '');
CREATE TABLE rules (id TEXT PRIMARY KEY, name TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 100, enabled INTEGER NOT NULL DEFAULT 1, pattern TEXT NOT NULL, match_field TEXT NOT NULL DEFAULT 'description', account_id TEXT REFERENCES accounts(id), min_amount INTEGER, max_amount INTEGER, direction TEXT NOT NULL DEFAULT 'any', category_id TEXT NOT NULL REFERENCES categories(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE balance_snapshots (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), balance INTEGER NOT NULL, captured_at TEXT NOT NULL, UNIQUE(account_id,captured_at));
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE tax_payments (id TEXT PRIMARY KEY, year INTEGER NOT NULL, jurisdiction TEXT NOT NULL CHECK(jurisdiction IN ('federal','state')), paid_on TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), notes TEXT NOT NULL DEFAULT '', transaction_id TEXT UNIQUE REFERENCES transactions(id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, credential_version TEXT NOT NULL);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE connections (id TEXT PRIMARY KEY, secret TEXT NOT NULL, last_success TEXT, last_error TEXT, status TEXT NOT NULL DEFAULT 'connected');
CREATE TABLE jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', payload TEXT NOT NULL DEFAULT '{}', progress TEXT NOT NULL DEFAULT '', error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, lease_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE imports (id TEXT PRIMARY KEY, name TEXT NOT NULL, fingerprint TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, row_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE access_tokens (id TEXT PRIMARY KEY, name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_used_at TEXT, client_id TEXT);
CREATE TABLE oauth_clients (id TEXT PRIMARY KEY, name TEXT NOT NULL, redirect_uris TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE oauth_codes (code_hash TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES oauth_clients(id), redirect_uri TEXT NOT NULL, challenge TEXT NOT NULL, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL, resource TEXT NOT NULL);
CREATE TABLE idempotency (key TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE VIRTUAL TABLE transaction_search USING fts5(description,merchant,notes,content='transactions',content_rowid='rowid');
CREATE TRIGGER tx_search_insert AFTER INSERT ON transactions BEGIN INSERT INTO transaction_search(rowid,description,merchant,notes) VALUES(new.rowid,new.description,new.merchant,new.notes); END;
CREATE TRIGGER tx_search_delete AFTER DELETE ON transactions BEGIN INSERT INTO transaction_search(transaction_search,rowid,description,merchant,notes) VALUES('delete',old.rowid,old.description,old.merchant,old.notes); END;
CREATE TRIGGER tx_search_update AFTER UPDATE ON transactions BEGIN INSERT INTO transaction_search(transaction_search,rowid,description,merchant,notes) VALUES('delete',old.rowid,old.description,old.merchant,old.notes); INSERT INTO transaction_search(rowid,description,merchant,notes) VALUES(new.rowid,new.description,new.merchant,new.notes); END;
CREATE VIEW ledger_entries AS SELECT t.id,t.id transaction_id,t.account_id,t.posted,t.amount,t.category_id,t.type,t.pending,t.reviewed,t.deleted,a.currency FROM transactions t JOIN accounts a ON a.id=t.account_id WHERE NOT EXISTS(SELECT 1 FROM splits s WHERE s.transaction_id=t.id) UNION ALL SELECT s.id,t.id,t.account_id,t.posted,s.amount,s.category_id,s.type,t.pending,t.reviewed,t.deleted,a.currency FROM splits s JOIN transactions t ON t.id=s.transaction_id JOIN accounts a ON a.id=t.account_id;

CREATE TABLE write_guards (id TEXT PRIMARY KEY, valid INTEGER NOT NULL CHECK(valid=1));
